  [talent_worlds_charge_3]="$ICON $VOID Subject: three violet ripple rings spreading in dark space around a tiny glowing figure, a small star above."
  [talent_mycelium_network]="$ICON $MYC Subject: a large glowing mushroom with thin luminous threads spreading from its stem to three small mushrooms."
  [talent_neurospores]="$ICON $MYC Subject: a puff of glowing green spores drifting around a small brain silhouette."
  [talent_neurosymbiosis]="$ICON $MYC Subject: two hands joined by glowing green fungal threads."
  [talent_net_nodes_1]="$ICON $MYC Subject: a mushroom with one small sprout beside it and a plus sign."
  [talent_net_nodes_2]="$ICON $MYC Subject: three mushrooms of growing size in a row."
