  [talent_net_sense]="$ICON $MYC Subject: a mushroom with a watching eye on its cap."
  [talent_net_recall]="$ICON $MYC Subject: a large mother mushroom with a curved arrow returning to it."
  [talent_net_shared]="$ICON $MYC Subject: two different coloured mushrooms joined by a thread."
  [talent_net_glow]="$ICON $MYC Subject: a glowing path of small mushrooms leading forward."
  [talent_awakening_bloom]="$ICON $MYC Subject: a giant glowing mushroom with spores rising and a green heart above."
  [talent_bloom_heal]="$ICON $MYC Subject: a green heart made of glowing spores."
  [talent_bloom_bark]="$ICON $MYC Subject: a mushroom stem covered with tough bark like a shield."
